import numpy as np

def engine(grid, action, data):
    g = grid.astype(int).copy()
    if action != 6:
        return g
    # find the 14-block "face" object (3x8 with 3 left column)
    mask = (g == 14)
    rows = np.where(mask.any(axis=1))[0]
    cols = np.where(mask.any(axis=0))[0]
    if len(rows) == 0 or len(cols) == 0:
        return g
    r0, r1 = int(rows.min()), int(rows.max())
    c0, c1 = int(cols.min()), int(cols.max())
    # extract the object (14, 3, 13 within bbox)
    obj = g[r0:r1+1, c0:c1+1]
    # clear original
    for r in range(r0, r1+1):
        for c in range(c0, c1+1):
            if g[r, c] in (14, 3, 13):
                g[r, c] = 5
    # move right by 3
    dr, dc = 0, 3
    nr0, nc0 = r0+dr, c0+dc
    if nr0+obj.shape[0] <= g.shape[0] and nc0+obj.shape[1] <= g.shape[1]:
        for i in range(obj.shape[0]):
            for j in range(obj.shape[1]):
                v = obj[i, j]
                if v in (14, 3, 13):
                    g[nr0+i, nc0+j] = v
    # bottom-right counter: decrement a 4 pixel
    # find rightmost 4 in last row
    last = g.shape[0]-1
    col4 = None
    for c in range(g.shape[1]-1, -1, -1):
        if g[last, c] == 4:
            col4 = c
            break
    if col4 is not None and col4 > 0:
        g[last, col4] = 5
        g[last, col4-1] = 4
    return g

def is_level_complete(grid):
    return False

